<?php
declare(strict_types=1);require __DIR__.'/config.php';require __DIR__.'/functions.php';if(session_status()!==PHP_SESSION_ACTIVE)session_start();$state=(string)($_GET['state']??'');if($state===''||!hash_equals($_SESSION['google_oauth_state']??'',$state)){flash('error','Permintaan login Google tidak valid.');redirect('login');}unset($_SESSION['google_oauth_state']);$clientId=getenv('GOOGLE_CLIENT_ID')?:'';$secret=getenv('GOOGLE_CLIENT_SECRET')?:'';$appUrl=rtrim(getenv('APP_URL')?:'https://bingkaiin.apinsdigital.my.id','/');$code=(string)($_GET['code']??'');
function google_request(string $url,array $options=[]):array{if(function_exists('curl_init')){$curl=curl_init($url);curl_setopt_array($curl,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>15,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_CUSTOMREQUEST=>$options['method']??'GET']);if(!empty($options['header']))curl_setopt($curl,CURLOPT_HTTPHEADER,array_filter(array_map('trim',explode("\r\n",$options['header']))));if(isset($options['content']))curl_setopt($curl,CURLOPT_POSTFIELDS,$options['content']);$raw=curl_exec($curl);curl_close($curl);}else{$context=stream_context_create(['http'=>array_merge(['ignore_errors'=>true,'timeout'=>15],$options)]);$raw=@file_get_contents($url,false,$context);}return is_string($raw)?(json_decode($raw,true)?:[]):[];}
if($code===''||$clientId===''||$secret===''){flash('error','Login Google tidak dapat diproses.');redirect('login');}$body=http_build_query(['code'=>$code,'client_id'=>$clientId,'client_secret'=>$secret,'redirect_uri'=>$appUrl.'/google/callback','grant_type'=>'authorization_code']);$token=google_request('https://oauth2.googleapis.com/token',['method'=>'POST','header'=>"Content-Type: application/x-www-form-urlencoded\r\n",'content'=>$body]);if(empty($token['access_token'])){flash('error','Google tidak mengembalikan akses yang valid.');redirect('login');}$info=google_request('https://openidconnect.googleapis.com/v1/userinfo',['header'=>'Authorization: Bearer '.$token['access_token']."\r\n"]);if(empty($info['sub'])||empty($info['email'])||empty($info['email_verified'])){flash('error','Email Google belum terverifikasi.');redirect('login');}$email=strtolower($info['email']);$stmt=$pdo->prepare('SELECT * FROM users WHERE google_id=? OR email=? LIMIT 1');$stmt->execute([$info['sub'],$email]);$user=$stmt->fetch();if($user){if(($user['status']??'active')!=='active'){flash('error','Akun ini sedang dinonaktifkan.');redirect('login');}$pdo->prepare("UPDATE users SET google_id=COALESCE(google_id,?),avatar=CASE WHEN avatar IS NULL OR avatar='' THEN ? ELSE avatar END WHERE id=?")->execute([$info['sub'],$info['picture']??null,$user['id']]);}else{$name=trim($info['name']??'Pengguna Google');$username=unique_username($pdo,$name);$pdo->prepare("INSERT INTO users(name,username,email,password,role,avatar,google_id,status) VALUES(?,?,?,?,'user',?,?,'active')")->execute([$name,$username,$email,password_hash(bin2hex(random_bytes(32)),PASSWORD_DEFAULT),$info['picture']??null,$info['sub']]);$id=(int)$pdo->lastInsertId();$stmt=$pdo->prepare('SELECT * FROM users WHERE id=?');$stmt->execute([$id]);$user=$stmt->fetch();}session_regenerate_id(true);$_SESSION['user']=['id'=>(int)$user['id'],'name'=>$user['name'],'email'=>$user['email'],'role'=>$user['role']];flash('success','Berhasil masuk menggunakan Google.');redirect('dashboard');
